package api
import "net/http"
func ListGauges(w http.ResponseWriter, r *http.Request) { w.Write([]byte("gauges")) }
func ReadGauge(w http.ResponseWriter, r *http.Request) { w.Write([]byte(r.PathValue("id"))) }
func Levels(w http.ResponseWriter, r *http.Request) { w.Write([]byte("levels")) }
func AddReading(w http.ResponseWriter, r *http.Request) { w.WriteHeader(202) }
func RawReadings(w http.ResponseWriter, r *http.Request) { w.Write([]byte("raw")) }
